window.FB_DASHBOARD_UNITS = [{"unit":1,"theme":"terrific / terrible；lately / shortly / hardly；indifferent / different…","cards":[{"w":"terrific","p":"adj.","d":"very good; very great in amount","c":"極好的；巨大的","s":"You did a terrific job on the school play; everyone loved it.","t":"你在學校話劇的表現好極了，大家都很喜歡。"},{"w":"terrible","p":"adj.","d":"very bad","c":"糟糕的；可怕的","s":"There was a terrible accident on the highway this morning.","t":"今天早上高速公路發生了一起可怕的車禍。"},{"w":"lately","p":"adv.","d":"recently","c":"最近","s":"I haven't seen Tom lately; is he still working in Taichung?","t":"我最近沒見到 Tom，他還在台中工作嗎？"},{"w":"shortly","p":"adv.","d":"soon","c":"不久；很快","s":"The train will arrive shortly, so please stand behind the yellow line.","t":"列車即將進站，請站在黃線後方。"},{"w":"hardly","p":"adv.","d":"almost not","c":"幾乎不","s":"I was so tired that I could hardly keep my eyes open in class.","t":"我累到上課時幾乎睜不開眼睛。"},{"w":"indifferent","p":"adj.","d":"not caring or interested","c":"漠不關心的；冷淡的","s":"How can you be indifferent to the suffering of animals in the shelter?","t":"你怎能對收容所裡受苦的動物漠不關心？"},{"w":"different","p":"adj.","d":"not the same","c":"不同的","s":"My sister and I look alike, but we have very different personalities.","t":"我和妹妹長得很像，但個性非常不同。"},{"w":"barely","p":"adv.","d":"only just; almost not","c":"勉強；幾乎不","s":"We barely caught the last bus home.","t":"我們勉強趕上了回家的末班公車。"},{"w":"fairly","p":"adv.","d":"quite; more than a little","c":"相當；頗","s":"The test was fairly easy, so most students finished early.","t":"考試相當簡單，所以大部分學生都提早寫完。"},{"w":"scarcely","p":"adv.","d":"almost not; only just","c":"幾乎不；剛剛","s":"There was scarcely any food left in the fridge.","t":"冰箱裡幾乎沒剩什麼食物了。"},{"w":"hospitable","p":"adj.","d":"friendly and welcoming to guests","c":"好客的；熱情的","s":"The villagers were so hospitable that they invited us to stay for dinner.","t":"村民非常好客，邀我們留下來吃晚餐。"},{"w":"hospital","p":"n.","d":"a place where sick or injured people are treated","c":"醫院","s":"He stayed in the hospital for a week after the car accident.","t":"車禍後他住院一週。"},{"w":"inhabit","p":"v.","d":"to live in a place","c":"居住於；棲息於","s":"Thousands of birds inhabit the wetlands along the river.","t":"數千隻鳥棲息在河邊的濕地。"},{"w":"habit","p":"n.","d":"something you do regularly","c":"習慣","s":"Checking your phone right after waking up is a hard habit to break.","t":"一醒來就看手機是個很難改掉的習慣。"},{"w":"costly","p":"adj.","d":"costing a lot of money; causing serious loss","c":"昂貴的；代價高的","s":"Fixing the old car would be too costly, so we sold it.","t":"修那台舊車太貴了，所以我們把它賣了。"},{"w":"elderly","p":"adj.","d":"old","c":"年長的","s":"Please give your seat to elderly passengers on the MRT.","t":"搭捷運時請讓座給年長的乘客。"},{"w":"deadly","p":"adj.","d":"able to cause death","c":"致命的","s":"Some mushrooms in the forest are deadly, so never eat wild ones.","t":"森林裡有些菇類是致命的，千萬別吃野生菇。"},{"w":"awful","p":"adj.","d":"very bad or unpleasant","c":"糟糕的；可怕的","s":"The food at that restaurant was awful, so we will never go back.","t":"那家餐廳的食物很糟，我們再也不去了。"},{"w":"awesome","p":"adj.","d":"very impressive; very good","c":"令人驚嘆的；超棒的","s":"The view from the top of Taipei 101 is awesome.","t":"從台北 101 頂端看出去的景色令人驚嘆。"},{"w":"overlook","p":"v.","d":"to fail to notice; to have a view of something from above","c":"忽略；俯瞰","s":"It's easy to overlook small mistakes when you check your own writing.","t":"檢查自己的文章時很容易忽略小錯誤。"},{"w":"oversee","p":"v.","d":"to watch and manage work or workers","c":"監督；監管","s":"A senior engineer was hired to oversee the building of the new bridge.","t":"公司聘請一位資深工程師監督新橋的興建。"},{"w":"pineapple","p":"n.","d":"a large tropical fruit with sweet yellow flesh","c":"鳳梨","s":"Taiwan's pineapple cakes are a popular gift for visitors.","t":"台灣的鳳梨酥是很受歡迎的伴手禮。"},{"w":"grapefruit","p":"n.","d":"a large round citrus fruit with a sour taste","c":"葡萄柚","s":"I drink a glass of grapefruit juice with my breakfast.","t":"我早餐時喝一杯葡萄柚汁。"}]},{"unit":2,"theme":"sympathetic / pathetic；innumerable / numerous；mischief / mischievous…","cards":[{"w":"sympathetic","p":"adj.","d":"showing that you understand and care about someone's problems","c":"有同情心的；體諒的","s":"My teacher was very sympathetic when I told her my dog had died.","t":"我告訴老師我的狗死了，她非常體諒我。"},{"w":"pathetic","p":"adj.","d":"making you feel pity; very bad or weak","c":"可憐的；差勁的","s":"The team's pathetic performance made the fans leave before halftime.","t":"球隊差勁的表現讓球迷在半場前就離開了。"},{"w":"innumerable","p":"adj.","d":"too many to be counted","c":"無數的；數不清的","s":"On a clear night in the mountains, you can see innumerable stars.","t":"晴朗的夜晚在山上，你能看到數不清的星星。"},{"w":"numerous","p":"adj.","d":"many","c":"許多的","s":"The singer has won numerous awards for her songs.","t":"這位歌手的歌曲贏得許多獎項。"},{"w":"mischief","p":"n.","d":"slightly bad behavior, especially by children","c":"淘氣；惡作劇","s":"The kids got into mischief while their parents were busy cooking.","t":"父母忙著煮飯時，孩子們在搗蛋。"},{"w":"mischievous","p":"adj.","d":"enjoying playing tricks; naughty","c":"調皮的；淘氣的","s":"The mischievous boy hid his sister's shoes under the bed.","t":"那個調皮的男孩把姊姊的鞋藏在床底下。"},{"w":"resent","p":"v.","d":"to feel angry about something unfair","c":"憤恨；不滿","s":"She resented being treated like a child by her older brother.","t":"她很不滿被哥哥當成小孩看待。"},{"w":"recreation","p":"n.","d":"things you do for fun when you are not working","c":"娛樂；消遣","s":"The park offers many kinds of recreation, such as biking and fishing.","t":"這座公園提供騎腳踏車、釣魚等多種休閒活動。"},{"w":"undermine","p":"v.","d":"to make something weaker gradually","c":"暗中破壞；逐漸削弱","s":"Constant criticism can undermine a child's confidence.","t":"不斷的批評會削弱孩子的自信。"},{"w":"undertake","p":"v.","d":"to agree to do a task; to start a job","c":"承擔；著手進行","s":"The city will undertake a big project to clean the river.","t":"市政府將著手進行一項整治河川的大計畫。"},{"w":"undergo","p":"v.","d":"to experience something, such as a change or operation","c":"經歷；接受（手術）","s":"My grandfather had to undergo heart surgery last month.","t":"我爺爺上個月必須接受心臟手術。"},{"w":"withdraw","p":"v.","d":"to take money out of a bank; to pull back","c":"提款；撤回；退出","s":"I need to withdraw some money from the ATM before we go to the market.","t":"去市場前我得先從提款機領點錢。"},{"w":"withhold","p":"v.","d":"to refuse to give something","c":"扣留；保留不給","s":"The company will withhold part of his salary until he returns the laptop.","t":"公司會扣住他部分薪水，直到他歸還筆電。"},{"w":"indispensable","p":"adj.","d":"absolutely necessary","c":"不可或缺的","s":"A good dictionary is indispensable for anyone learning a foreign language.","t":"對學外語的人來說，一本好字典是不可或缺的。"},{"w":"dispensable","p":"adj.","d":"not necessary; can be done without","c":"可有可無的；非必要的","s":"In hard times, companies cut dispensable costs such as parties and gifts.","t":"景氣不好時，公司會刪減派對、禮品等非必要開銷。"},{"w":"overtake","p":"v.","d":"to go past a moving vehicle; to become greater than","c":"超車；超越","s":"It is dangerous to overtake another car on a narrow mountain road.","t":"在狹窄山路上超車很危險。"},{"w":"overhear","p":"v.","d":"to hear what other people say without them knowing","c":"無意間聽到","s":"I overheard my parents planning a surprise party for my birthday.","t":"我無意中聽到爸媽在計畫我的生日驚喜派對。"},{"w":"outlook","p":"n.","d":"a general attitude; what is expected to happen","c":"看法；展望；前景","s":"Despite her illness, she has a positive outlook on life.","t":"儘管生病，她對人生仍抱持正面的看法。"},{"w":"outskirts","p":"n.","d":"the outer parts of a town or city","c":"郊區；市郊","s":"They bought a cheaper house on the outskirts of Taichung.","t":"他們在台中市郊買了一間比較便宜的房子。"},{"w":"outset","p":"n.","d":"the beginning","c":"開始；開端","s":"From the outset, the teacher made the rules of the class very clear.","t":"老師從一開始就把班規說得很清楚。"},{"w":"setback","p":"n.","d":"a problem that stops progress for a time","c":"挫折；阻礙","s":"The injury was a big setback, but she still made it to the finals.","t":"受傷是一大挫折，但她仍打進決賽。"},{"w":"outbreak","p":"n.","d":"the sudden start of a disease or war","c":"爆發","s":"The school closed for a week after an outbreak of flu.","t":"流感爆發後學校停課一週。"}]},{"unit":3,"theme":"shortsighted / nearsighted；wholesome / wholesale；invaluable / priceless / valueless…","cards":[{"w":"shortsighted","p":"adj.","d":"not thinking about the future results","c":"目光短淺的；短視的","s":"Cutting the education budget is a shortsighted decision.","t":"刪減教育預算是短視的決定。"},{"w":"nearsighted","p":"adj.","d":"unable to see things that are far away clearly","c":"近視的","s":"She is nearsighted, so she sits in the front row to see the board.","t":"她近視，所以坐第一排才看得清黑板。"},{"w":"wholesome","p":"adj.","d":"good for your health or morals","c":"有益健康的；健全的","s":"Parents want their children to eat wholesome food instead of fast food.","t":"父母希望孩子吃健康的食物而不是速食。"},{"w":"wholesale","p":"n./adj.","d":"the selling of goods in large amounts to shops","c":"批發（的）","s":"The shop buys vegetables at wholesale prices from the farmers.","t":"這家店以批發價向農民購買蔬菜。"},{"w":"invaluable","p":"adj.","d":"extremely useful or valuable","c":"極有價值的；非常寶貴的","s":"Your advice was invaluable; without it, I would have failed the interview.","t":"你的建議非常寶貴，沒有它我面試就失敗了。"},{"w":"priceless","p":"adj.","d":"so valuable that no price can be put on it","c":"無價的；極珍貴的","s":"The museum keeps the priceless paintings in a special room with guards.","t":"博物館把那些無價的畫作放在有警衛看守的特別展間。"},{"w":"valueless","p":"adj.","d":"having no value","c":"沒有價值的","s":"The old coins turned out to be valueless, so he gave them to his little brother.","t":"那些舊硬幣結果一文不值，他就送給弟弟了。"},{"w":"comprehensive","p":"adj.","d":"including everything or almost everything","c":"全面的；綜合的","s":"The guidebook gives comprehensive information about hotels, food, and transportation.","t":"這本旅遊書提供飯店、美食和交通的全面資訊。"},{"w":"comprehensible","p":"adj.","d":"easy to understand","c":"可理解的","s":"The teacher explained the difficult idea in comprehensible language.","t":"老師用淺顯易懂的語言解釋這個困難的概念。"}]}];
